export function slackCredentials(
  env: Record<string, string | undefined> = process.env,
): SlackCredentials | null {
  const clientId = env.SLACK_TRIAGEDESK_CLIENT_ID;
  const clientSecret = env.SLACK_TRIAGEDESK_CLIENT_SECRET;
  const signingSecret = env.SLACK_TRIAGEDESK_SIGNING_SECRET;
  if (!clientId || !clientSecret || !signingSecret) return null;
  return { clientId, clientSecret, signingSecret };
}

/** True when this deployment can actually run an install. The workspace surface
 *  reads this so the button reflects what pressing it will do, rather than
 *  sending somebody to an error page. */
export function slackConfigured(env: Record<string, string | undefined> = process.env): boolean {
  return slackCredentials(env) !== null;
}

